  1	//! Phase-probed 1p/1c round-trip measurement cells over the
  2	//! zc-ring-x1 primitives.
  3	//!
  4	//! One **cell** is a main -> worker -> main round trip at a
  5	//! given ring flavor and thread placement, driven for a fixed
  6	//! duration. Each protocol phase is measured by its own
  7	//! [`TProbe`] and, on Linux, the cross-core cache-fill counters
  8	//! are collected in-process (no perf(1) needed):
  9	//!
 10	//! - `main send` / `worker send`: the producer's reserve +
 11	//!   fill + commit, including any stall acquiring peer-written
 12	//!   cache lines. The ring is never full here (one message in
 13	//!   flight, at any depth from 1 up), so no send ever waits
 14	//!   for space.
 15	//! - `worker recv` / `main recv`: the consumer's spin wait +
 16	//!   read + release. These absorb the in-flight half trip.
 17	//! - `... recv spin` / `... recv attempts`: the wait inside the
 18	//!   recv phase, decomposed: spin time (first failed attempt ->
 19	//!   reserve success) and the attempt count, recorded only for
 20	//!   reserves that actually waited.
 21	//!
 22	//! A **streaming cell** is the other shape: the producer sends
 23	//! a counter as fast as the ring admits for a fixed duration
 24	//! and the consumer drains it, the depth in play as slack, and
 25	//! the fill counters divided by the messages moved say how
 26	//! many lines crossed per message while streaming, the number
 27	//! the round-trip cell cannot give.
 28	//!
 29	//! The binaries:
 30	//!
 31	//! - `tp-cell` runs one cell and prints the probe reports.
 32	//! - `tp-matrix` runs every flavor × placement cell and emits
 33	//!   markdown tables.
 34	//! - `tp-stream` runs the streaming cell over the same matrix.
 35	
 36	use std::time::{Duration, Instant};
 37	
 38	use tp_runner::{LINE_BYTES, LineBuf, STOP, drive, pin_to_cpu, spin, unpin_current};
 39	use tprobe::TProbe;
 40	use tprobe::ticks;
 41	use zc_ring_x1::CACHE_LINE_SIZE;
 42	
 43	// The runner's line-aligned regions must be aligned the way
 44	// the rings want them.
 45	const _: () = assert!(LINE_BYTES == CACHE_LINE_SIZE);
 46	
 47	/// Bytes a v0 region needs: the four-line header, then the
 48	/// slots. v0 exports no size function of its own, its header
 49	/// being a fixed shape.
 50	fn v0_region_size(slot_size: u32, capacity: u32) -> u64 {
 51	    size_of::<zc_ring_x1::spsc::v0::Header>() as u64 + slot_size as u64 * capacity as u64
 52	}
 53	
 54	/// The ring flavor a cell measures, named `xpsc-vN` after its
 55	/// module path, every version included so the A/B is one run.
 56	#[derive(Clone, Copy, PartialEq, Eq)]
 57	pub enum Flavor {
 58	    /// The SPSC v0 ring (`reserve_slot_with` both ends).
 59	    SpscV0,
 60	    /// The SPSC v1 seam-word ring (same surface, per-slot seq).
 61	    SpscV1,
 62	    /// The SPSC v2 in-slot seq ring (same surface, the seq at
 63	    /// the front of its slot).
 64	    SpscV2,
 65	    /// The MPSC v0 ring at 1p/1c (`send_with` producers).
 66	    MpscV0,
 67	    /// The MPSC v1 equality-seq ring at 1p/1c (same surface,
 68	    /// runs at depth 1).
 69	    MpscV1,
 70	}
 71	
 72	/// Every flavor, in report order.
 73	pub const FLAVORS: [Flavor; 5] = [
 74	    Flavor::SpscV0,
 75	    Flavor::SpscV1,
 76	    Flavor::SpscV2,
 77	    Flavor::MpscV0,
 78	    Flavor::MpscV1,
 79	];
 80	
 81	impl Flavor {
 82	    /// Lowercase name for labels and CLI parsing.
 83	    pub fn as_str(self) -> &'static str {
 84	        match self {
 85	            Flavor::SpscV0 => "spsc-v0",
 86	            Flavor::SpscV1 => "spsc-v1",
 87	            Flavor::SpscV2 => "spsc-v2",
 88	            Flavor::MpscV0 => "mpsc-v0",
 89	            Flavor::MpscV1 => "mpsc-v1",
 90	        }
 91	    }
 92	
 93	    /// The smallest depth the flavor's protocol runs at. The
 94	    /// MPSC v0 ring's committed and released seq values coincide
 95	    /// at capacity 1 and its `init` rejects it, so its cells
 96	    /// start at 2. v1 fixed that and runs from 1.
 97	    pub fn min_depth(self) -> u32 {
 98	        match self {
 99	            Flavor::MpscV0 => 2,
100	            _ => 1,
101	        }
102	    }
103	}
104	
105	/// The cache-fill counter totals for one cell (Linux, `None`
106	/// in [`CellResult`] when unavailable).
107	pub struct FillCounts {
108	    /// Demand fills served from another core's cache: the
109	    /// cross-core line-transfer signal.
110	    pub lcl_cache: u64,
111	    /// Demand fills served from the core's own L2.
112	    pub lcl_l2: u64,
113	    /// Demand fills served from local DRAM.
114	    pub lcl_dram: u64,
115	}
116	
117	/// One cell's outcome: the eight probes in trip order and the
118	/// fill counters.
119	pub struct CellResult {
120	    /// Trip order: main send, worker recv, worker recv spin,
121	    /// worker recv attempts, worker send, main recv, main recv
122	    /// spin, main recv attempts.
123	    pub probes: [TProbe; 8],
124	    /// Round trips completed (== every probe's phase count).
125	    pub rts: u64,
126	    /// Fill counters, when the platform provides them.
127	    pub fills: Option<FillCounts>,
128	}
129	
130	/// The three per-cell fill counters, opened before the worker
131	/// spawns so `inherit` covers it.
132	#[cfg(target_os = "linux")]
133	struct Fills {
134	    lcl_cache: tp_runner::perf::ProcessCounter,
135	    lcl_l2: tp_runner::perf::ProcessCounter,
136	    lcl_dram: tp_runner::perf::ProcessCounter,
137	}
138	
139	#[cfg(target_os = "linux")]
140	impl Fills {
141	    /// Open + enable all three, returning `None` (with a
142	    /// one-line note) where perf_event_open is unavailable.
143	    fn open() -> Option<Fills> {
144	        use tp_runner::perf::{
145	            ProcessCounter, ZEN2_FILLS_LCL_CACHE, ZEN2_FILLS_LCL_DRAM, ZEN2_FILLS_LCL_L2,
146	        };
147	        let open = |config| ProcessCounter::new_raw(config);
148	        match (
149	            open(ZEN2_FILLS_LCL_CACHE),
150	            open(ZEN2_FILLS_LCL_L2),
151	            open(ZEN2_FILLS_LCL_DRAM),
152	        ) {
153	            (Ok(mut lcl_cache), Ok(mut lcl_l2), Ok(mut lcl_dram)) => {
154	                lcl_cache.enable().ok()?;
155	                lcl_l2.enable().ok()?;
156	                lcl_dram.enable().ok()?;
157	                Some(Fills {
158	                    lcl_cache,
159	                    lcl_l2,
160	                    lcl_dram,
161	                })
162	            }
163	            (r, _, _) => {
164	                if let Err(e) = r {
165	                    eprintln!("note: fill counters unavailable ({e}); fills/RT will be absent");
166	                }
167	                None
168	            }
169	        }
170	    }
171	
172	    /// Disable and read the totals.
173	    fn finish(mut self) -> Option<FillCounts> {
174	        self.lcl_cache.disable().ok()?;
175	        self.lcl_l2.disable().ok()?;
176	        self.lcl_dram.disable().ok()?;
177	        Some(FillCounts {
178	            lcl_cache: self.lcl_cache.read().ok()?,
179	            lcl_l2: self.lcl_l2.read().ok()?,
180	            lcl_dram: self.lcl_dram.read().ok()?,
181	        })
182	    }
183	}
