185	/// The three probes each recv site records into.
186	struct RecvProbes {
187	    /// The whole recv phase (spin wait + read + release).
188	    phase: TProbe,
189	    /// Wait only: first failed attempt -> reserve success,
190	    /// recorded only when the reserve actually waited.
191	    spin: TProbe,
192	    /// Attempt count per waiting reserve (counts probe).
193	    attempts: TProbe,
194	}
195	
196	impl RecvProbes {
197	    /// Build the three probes for the `side` ("main"/"worker")
198	    /// of a `flavor` run.
199	    fn new(flavor: Flavor, side: &str) -> Self {
200	        let flavor = flavor.as_str();
201	        RecvProbes {
202	            phase: TProbe::new(&format!("{flavor} {side} recv (reserve+release)")),
203	            spin: TProbe::new(&format!("{flavor} {side} recv spin (wait only)")),
204	            attempts: TProbe::new_counts(&format!("{flavor} {side} recv attempts")),
205	        }
206	    }
207	}
208	
209	/// One instrumented receive: `reserve` performs the endpoint's
210	/// reserve/read/release under a spin policy that must stamp
211	/// `spin_start` on its first failed attempt and keep `attempts`
212	/// current, then returns the received value. Records the phase
213	/// (and, when a wait happened, spin time + attempts) into
214	/// `probes`, unless the value is [`STOP`], which passes
215	/// through unrecorded.
216	fn instrumented_recv(
217	    probes: &mut RecvProbes,
218	    reserve: impl FnOnce(&mut u32, &mut u64) -> u64,
219	) -> u64 {
220	    let mut attempts: u32 = 0;
221	    let mut spin_start: u64 = 0;
222	    let s = ticks::read_ticks();
223	    let v = reserve(&mut attempts, &mut spin_start);
224	    let spin_end = if attempts > 0 { ticks::read_ticks() } else { 0 };
225	    let e = ticks::read_ticks();
226	    if v == STOP {
227	        return v;
228	    }
229	    probes.phase.record(e.wrapping_sub(s));
230	    if attempts > 0 {
231	        probes.spin.record(spin_end.wrapping_sub(spin_start));
232	        probes.attempts.record(attempts as u64);
233	    }
234	    v
235	}
236	
237	/// Run one measurement cell: pin (or unpin) the calling thread,
238	/// open the fill counters, drive `dur` worth of round trips at
239	/// `flavor` and ring `depth` with the worker on `pin.1`, and
240	/// return probes + counters. The caller's thread affinity is
241	/// left as the cell set it.
242	pub fn run_cell(
243	    flavor: Flavor,
244	    dur: Duration,
245	    pin: Option<(usize, usize)>,
246	    depth: u32,
247	) -> CellResult {
248	    match pin {
249	        Some((main_cpu, _)) => pin_to_cpu(main_cpu),
250	        None => unpin_current(),
251	    }
252	    #[cfg(target_os = "linux")]
253	    let fills = Fills::open();
254	    let worker = pin.map(|(_, w)| w);
255	    let probes = match flavor {
256	        Flavor::SpscV0 => run_spsc_v0(dur, worker, depth),
257	        Flavor::SpscV1 => run_spsc_v1(dur, worker, depth),
258	        Flavor::SpscV2 => run_spsc_v2(dur, worker, depth),
259	        Flavor::MpscV0 => run_mpsc_v0(dur, worker, depth),
260	        Flavor::MpscV1 => run_mpsc_v1(dur, worker, depth),
261	    };
262	    #[cfg(target_os = "linux")]
263	    let fills = fills.and_then(Fills::finish);
264	    #[cfg(not(target_os = "linux"))]
265	    let fills = None;
266	    let rts = probes[0].count();
267	    CellResult { probes, rts, fills }
268	}
