270	/// Define an SPSC cell body over the ring at `$ring`, its
271	/// regions sized by `$size(slot_size, depth)`: two rings, both
272	/// ends `reserve_slot_with` under the [`spin`] policy (recv
273	/// sites instrumented). The SPSC versions share the endpoint
274	/// surface and differ by path, so one body serves them all and
275	/// the A/B measures the protocol alone.
276	macro_rules! spsc_cell {
277	    ($name:ident, $ring:path, $size:path, $flavor:expr) => {
278	        fn $name(dur: Duration, worker_cpu: Option<usize>, depth: u32) -> [TProbe; 8] {
279	            use $ring as Ring;
280	            let slot = CACHE_LINE_SIZE as u32;
281	            let mut req_region = LineBuf::new($size(slot, depth));
282	            let mut resp_region = LineBuf::new($size(slot, depth));
283	            let (mut req_tx, mut req_rx) = Ring::init(req_region.as_mut_bytes(), slot, depth)
284	                .unwrap() // OK: the region is sized by the ring's own size function and line-aligned
285	                .split();
286	            let (mut resp_tx, mut resp_rx) = Ring::init(resp_region.as_mut_bytes(), slot, depth)
287	                .unwrap() // OK: the region is sized by the ring's own size function and line-aligned
288	                .split();
289	
290	            std::thread::scope(|s| {
291	                let worker = s.spawn(move || {
292	                    if let Some(cpu) = worker_cpu {
293	                        pin_to_cpu(cpu);
294	                    }
295	                    let mut recv = RecvProbes::new($flavor, "worker");
296	                    let mut send_probe = TProbe::new(&format!(
297	                        "{} worker send (reserve+commit)",
298	                        $flavor.as_str()
299	                    ));
300	                    loop {
301	                        let v = instrumented_recv(&mut recv, |attempts, spin_start| {
302	                            let slot = req_rx
303	                                .reserve_slot_with::<u64>(|a| {
304	                                    if a == 0 {
305	                                        *spin_start = ticks::read_ticks();
306	                                    }
307	                                    *attempts = a + 1;
308	                                    core::hint::spin_loop();
309	                                    true
310	                                })
311	                                .expect("spin never gives up");
312	                            let v = *slot;
313	                            slot.release();
314	                            v
315	                        });
316	                        if v == STOP {
317	                            break;
318	                        }
319	                        let s = ticks::read_ticks();
320	                        let mut slot = resp_tx
321	                            .reserve_slot_with::<u64>(spin)
322	                            .expect("spin never gives up");
323	                        *slot = v;
324	                        slot.commit();
325	                        send_probe.record(ticks::read_ticks().wrapping_sub(s));
326	                    }
327	                    (recv, send_probe)
328	                });
329	
330	                let mut send_probe =
331	                    TProbe::new(&format!("{} main send (reserve+commit)", $flavor.as_str()));
332	                let mut recv = RecvProbes::new($flavor, "main");
333	                drive(
334	                    dur,
335	                    |v| {
336	                        let s = ticks::read_ticks();
337	                        let mut slot = req_tx
338	                            .reserve_slot_with::<u64>(spin)
339	                            .expect("spin never gives up");
340	                        *slot = v;
341	                        slot.commit();
342	                        send_probe.record(ticks::read_ticks().wrapping_sub(s));
343	                    },
344	                    || {
345	                        instrumented_recv(&mut recv, |attempts, spin_start| {
346	                            let slot = resp_rx
347	                                .reserve_slot_with::<u64>(|a| {
348	                                    if a == 0 {
349	                                        *spin_start = ticks::read_ticks();
350	                                    }
351	                                    *attempts = a + 1;
352	                                    core::hint::spin_loop();
353	                                    true
354	                                })
355	                                .expect("spin never gives up");
356	                            let v = *slot;
357	                            slot.release();
358	                            v
359	                        })
360	                    },
361	                );
362	                let mut slot = req_tx
363	                    .reserve_slot_with::<u64>(spin)
364	                    .expect("spin never gives up");
365	                *slot = STOP;
366	                slot.commit();
367	                let (worker_recv, worker_send) = worker.join().expect("worker panicked");
368	                [
369	                    send_probe,
370	                    worker_recv.phase,
371	                    worker_recv.spin,
372	                    worker_recv.attempts,
373	                    worker_send,
374	                    recv.phase,
375	                    recv.spin,
376	                    recv.attempts,
377	                ]
378	            })
379	        }
380	    };
381	}
