383	spsc_cell!(
384	    run_spsc_v0,
385	    zc_ring_x1::spsc::v0::Ring,
386	    v0_region_size,
387	    Flavor::SpscV0
388	);
389	spsc_cell!(
390	    run_spsc_v1,
391	    zc_ring_x1::spsc::v1::Ring,
392	    zc_ring_x1::spsc::v1::region_size,
393	    Flavor::SpscV1
394	);
395	spsc_cell!(
396	    run_spsc_v2,
397	    zc_ring_x1::spsc::v2::Ring,
398	    zc_ring_x1::spsc::v2::region_size,
399	    Flavor::SpscV2
400	);
