402	/// Define an MPSC cell body over the ring at `$ring`, its
403	/// regions sized by `$size(slot_size, depth)`: two rings at
404	/// 1p/1c, producers `send_with` (closure fill), the consumer
405	/// `reserve_slot_with`, both under the [`spin`] policy (recv
406	/// sites instrumented). The MPSC versions share the endpoint
407	/// surface and differ by path, as the SPSC ones do, so one body
408	/// serves both and the A/B measures the protocol alone.
409	macro_rules! mpsc_cell {
410	    ($name:ident, $ring:path, $size:path, $flavor:expr) => {
411	        fn $name(dur: Duration, worker_cpu: Option<usize>, depth: u32) -> [TProbe; 8] {
412	            use $ring as MpscRing;
413	            let slot = CACHE_LINE_SIZE as u32;
414	            let mut req_region = LineBuf::new($size(slot, depth));
415	            let mut resp_region = LineBuf::new($size(slot, depth));
416	            let (req_tx, mut req_rx) = MpscRing::init(req_region.as_mut_bytes(), slot, depth)
417	                .unwrap() // OK: the region is sized by mpsc_region_size and line-aligned
418	                .split();
419	            let (resp_tx, mut resp_rx) = MpscRing::init(resp_region.as_mut_bytes(), slot, depth)
420	                .unwrap() // OK: the region is sized by mpsc_region_size and line-aligned
421	                .split();
422	
423	            std::thread::scope(|s| {
424	                let worker = s.spawn(move || {
425	                    if let Some(cpu) = worker_cpu {
426	                        pin_to_cpu(cpu);
427	                    }
428	                    let mut recv = RecvProbes::new($flavor, "worker");
429	                    let mut send_probe =
430	                        TProbe::new(&format!("{} worker send (send_with)", $flavor.as_str()));
431	                    loop {
432	                        let v = instrumented_recv(&mut recv, |attempts, spin_start| {
433	                            let slot = req_rx
434	                                .reserve_slot_with::<u64>(|a| {
435	                                    if a == 0 {
436	                                        *spin_start = ticks::read_ticks();
437	                                    }
438	                                    *attempts = a + 1;
439	                                    core::hint::spin_loop();
440	                                    true
441	                                })
442	                                .expect("spin never gives up");
443	                            let v = *slot;
444	                            slot.release();
445	                            v
446	                        });
447	                        if v == STOP {
448	                            break;
449	                        }
450	                        let s = ticks::read_ticks();
451	                        resp_tx
452	                            .send_with::<u64>(spin, |m| *m = v)
453	                            .expect("spin never gives up");
454	                        send_probe.record(ticks::read_ticks().wrapping_sub(s));
455	                    }
456	                    (recv, send_probe)
457	                });
458	
459	                let mut send_probe =
460	                    TProbe::new(&format!("{} main send (send_with)", $flavor.as_str()));
461	                let mut recv = RecvProbes::new($flavor, "main");
462	                drive(
463	                    dur,
464	                    |v| {
465	                        let s = ticks::read_ticks();
466	                        req_tx
467	                            .send_with::<u64>(spin, |m| *m = v)
468	                            .expect("spin never gives up");
469	                        send_probe.record(ticks::read_ticks().wrapping_sub(s));
470	                    },
471	                    || {
472	                        instrumented_recv(&mut recv, |attempts, spin_start| {
473	                            let slot = resp_rx
474	                                .reserve_slot_with::<u64>(|a| {
475	                                    if a == 0 {
476	                                        *spin_start = ticks::read_ticks();
477	                                    }
478	                                    *attempts = a + 1;
479	                                    core::hint::spin_loop();
480	                                    true
481	                                })
482	                                .expect("spin never gives up");
483	                            let v = *slot;
484	                            slot.release();
485	                            v
486	                        })
487	                    },
488	                );
489	                req_tx
490	                    .send_with::<u64>(spin, |m| *m = STOP)
491	                    .expect("spin never gives up");
492	                let (worker_recv, worker_send) = worker.join().expect("worker panicked");
493	                [
494	                    send_probe,
495	                    worker_recv.phase,
496	                    worker_recv.spin,
497	                    worker_recv.attempts,
498	                    worker_send,
499	                    recv.phase,
500	                    recv.spin,
501	                    recv.attempts,
502	                ]
503	            })
504	        }
505	    };
506	}
507	
508	mpsc_cell!(
509	    run_mpsc_v0,
510	    zc_ring_x1::mpsc::v0::MpscRing,
511	    zc_ring_x1::mpsc::v0::mpsc_region_size,
512	    Flavor::MpscV0
513	);
514	mpsc_cell!(
515	    run_mpsc_v1,
516	    zc_ring_x1::mpsc::v1::MpscRing,
517	    zc_ring_x1::mpsc::v1::mpsc_region_size,
518	    Flavor::MpscV1
519	);
