521	/// One streaming cell's outcome.
522	pub struct StreamResult {
523	    /// Messages the consumer received, the stop sentinel not
524	    /// counted.
525	    pub msgs: u64,
526	    /// Wall-clock seconds from the first send to the consumer
527	    /// seeing the stop sentinel.
528	    pub secs: f64,
529	    /// Fill counters over the whole stream, when the platform
530	    /// provides them.
531	    pub fills: Option<FillCounts>,
532	}
533	
534	/// Messages between the producer's wall-clock checks, as
535	/// `drive` spaces its checks.
536	const STREAM_CHECK_EVERY: u64 = 4096;
537	
538	/// Run one streaming cell: open the fill counters, stream a
539	/// counter for `dur` at `flavor` and ring `depth` from a
540	/// producer thread on `pin.0` to a consumer thread on `pin.1`,
541	/// and return the count, the elapsed time, and the counters.
542	///
543	/// - Both ends are spawned threads that pin themselves, as the
544	///   demo's streams do, so the calling thread's affinity is
545	///   untouched and the two sides start alike.
546	/// - The producer sends as fast as the ring admits under the
547	///   [`spin`] policy, so the ring sits full whenever the
548	///   consumer is the slower side, and the consumer asserts the
549	///   counter's order.
550	/// - The elapsed time ends when the consumer has seen the stop
551	///   sentinel, so the last message's drain is inside it.
552	pub fn run_stream(
553	    flavor: Flavor,
554	    dur: Duration,
555	    pin: Option<(usize, usize)>,
556	    depth: u32,
557	) -> StreamResult {
558	    unpin_current();
559	    #[cfg(target_os = "linux")]
560	    let fills = Fills::open();
561	    let (msgs, secs) = match flavor {
562	        Flavor::SpscV0 => stream_spsc_v0(dur, pin, depth),
563	        Flavor::SpscV1 => stream_spsc_v1(dur, pin, depth),
564	        Flavor::SpscV2 => stream_spsc_v2(dur, pin, depth),
565	        Flavor::MpscV0 => stream_mpsc_v0(dur, pin, depth),
566	        Flavor::MpscV1 => stream_mpsc_v1(dur, pin, depth),
567	    };
568	    #[cfg(target_os = "linux")]
569	    let fills = fills.and_then(Fills::finish);
570	    #[cfg(not(target_os = "linux"))]
571	    let fills = None;
572	    StreamResult { msgs, secs, fills }
573	}
