590	/// Define an SPSC streaming cell body over the ring at `$ring`,
591	/// its region sized by `$size(slot_size, depth)`: one ring,
592	/// the producer spawned on `pin.0`, the consumer on `pin.1`.
593	/// Returns the messages moved and the seconds.
594	macro_rules! spsc_stream {
595	    ($name:ident, $ring:path, $size:path) => {
596	        fn $name(dur: Duration, pin: Option<(usize, usize)>, depth: u32) -> (u64, f64) {
597	            use $ring as Ring;
598	            let slot = CACHE_LINE_SIZE as u32;
599	            let mut region = LineBuf::new($size(slot, depth));
600	            let (mut tx, mut rx) = Ring::init(region.as_mut_bytes(), slot, depth)
601	                .unwrap() // OK: the region is sized by the ring's own size function and line-aligned
602	                .split();
603	            let start = Instant::now();
604	            let msgs = std::thread::scope(|s| {
605	                s.spawn(move || {
606	                    if let Some((p, _)) = pin {
607	                        pin_to_cpu(p);
608	                    }
609	                    let mut counter: u64 = 0;
610	                    loop {
611	                        for _ in 0..STREAM_CHECK_EVERY {
612	                            let mut slot = tx
613	                                .reserve_slot_with::<u64>(zc_ring_x1::policy::spin)
614	                                .expect("spin never gives up");
615	                            *slot = counter;
616	                            slot.commit();
617	                            counter += 1;
618	                        }
619	                        if start.elapsed() >= dur {
620	                            break;
621	                        }
622	                    }
623	                    let mut slot = tx
624	                        .reserve_slot_with::<u64>(zc_ring_x1::policy::spin)
625	                        .expect("spin never gives up");
626	                    *slot = STOP;
627	                    slot.commit();
628	                });
629	                let consumer = s.spawn(move || {
630	                    if let Some((_, c)) = pin {
631	                        pin_to_cpu(c);
632	                    }
633	                    drain_stream(|| {
634	                        let slot = rx
635	                            .reserve_slot_with::<u64>(zc_ring_x1::policy::spin)
636	                            .expect("spin never gives up");
637	                        let v = *slot;
638	                        slot.release();
639	                        v
640	                    })
641	                });
642	                consumer.join().expect("consumer panicked")
643	            });
644	            (msgs, start.elapsed().as_secs_f64())
645	        }
646	    };
647	}
