 47	/// Bytes a v0 region needs: the four-line header, then the
 48	/// slots. v0 exports no size function of its own, its header
 49	/// being a fixed shape.
 50	fn v0_region_size(slot_size: u32, capacity: u32) -> u64 {
 51	    size_of::<zc_ring_x1::spsc::v0::Header>() as u64 + slot_size as u64 * capacity as u64
 52	}
