    13	use tp_runner::{CommonArgs, parse_pin, report};
    14	use tprobe::fmt::fmt_commas;
    15	
    16	/// Banner: name, version, and tagline on one line, the first
    17	/// line of every run and of `-h`/`--help`.
    18	const TOP_ABOUT: &str = concat!(
