    40	    All,
    41	}
    42	
    43	/// The tp-cell CLI.
    44	#[derive(Parser, Debug)]
    45	#[command(name = "tp-cell", version, about = TOP_ABOUT, max_term_width = 80)]
    46	struct Cli {
    47	    /// Ring flavor(s) to run
    48	    ///
    49	    /// One cell is a main -> worker -> main round trip over two
    50	    /// rings of the given flavor: main sends a counter on the
    51	    /// request ring, the worker echoes it on the response ring.
    52	    /// Each protocol phase (send, recv, recv spin, recv
