   112	//! tp-stream: run the streaming cell over every flavor,
   113	//! placement, and depth, and emit one markdown table: ns per
   114	//! message, messages moved, and cross-core cache-line fills per
   115	//! message. The streaming sibling of `tp-matrix`, whose cell
   116	//! keeps one message in flight and so cannot show what a
   117	//! full ring costs per message.
   118	
   119	use clap::Parser;
   120	
   121	use tp_matrix::{FLAVORS, Flavor, StreamResult, run_stream};
   122	use tp_runner::topo::{Placement, discover_placements};
   123	use tp_runner::{Cfg, CommonArgs};
   124	
   125	/// Banner: name, version, and tagline on one line, the first
   126	/// line of every run and of `-h`/`--help`.
   127	const TOP_ABOUT: &str = concat!(
   128	    "tp-stream ",
   129	    env!("CARGO_PKG_VERSION"),
   130	    " - run the streaming matrix, one markdown table out"
   131	);
   132	
   133	/// The tp-stream CLI.
   134	#[derive(Parser, Debug)]
   135	#[command(name = "tp-stream", version, about = TOP_ABOUT, max_term_width = 80)]
   136	struct Cli {
   137	    #[command(flatten)]
   138	    common: CommonArgs,
   139	}
   140	
   141	/// `fills/msg` cell: 3 decimals, or 4 when the value is tiny
   142	/// (the SMT cells), `-` when counters were unavailable.
   143	fn fills_cell(res: &StreamResult) -> String {
   144	    match &res.fills {
   145	        Some(f) => {
   146	            let v = f.lcl_cache as f64 / res.msgs.max(1) as f64;
   147	            if v < 0.01 {
   148	                format!("{v:.4}")
   149	            } else {
   150	                format!("{v:.3}")
   151	            }
   152	        }
   153	        None => "-".to_string(),
   154	    }
   155	}
   156	
   157	/// Print `rows` as an aligned markdown table under `headers`.
   158	/// The first two columns left-aligned, the rest right-aligned.
   159	fn print_table(headers: &[&str], rows: &[Vec<String>]) {
   160	    let mut w: Vec<usize> = headers.iter().map(|h| h.len()).collect();
   161	    for row in rows {
   162	        for (i, cell) in row.iter().enumerate() {
   163	            w[i] = w[i].max(cell.len());
   164	        }
   165	    }
   166	    let fmt_row = |cells: &[String]| {
   167	        let mut line = String::from("|");
   168	        for (i, cell) in cells.iter().enumerate() {
   169	            if i < 2 {
   170	                line.push_str(&format!(" {:<w$} |", cell, w = w[i]));
   171	            } else {
   172	                line.push_str(&format!(" {:>w$} |", cell, w = w[i]));
   173	            }
   174	        }
   175	        line
   176	    };
   177	    let headers: Vec<String> = headers.iter().map(|h| h.to_string()).collect();
   178	    println!("{}", fmt_row(&headers));
   179	    let mut sep = String::from("|");
   180	    for (i, width) in w.iter().enumerate() {
   181	        if i < 2 {
   182	            sep.push_str(&format!("{}|", "-".repeat(width + 2)));
   183	        } else {
   184	            sep.push_str(&format!("{}:|", "-".repeat(width + 1)));
   185	        }
   186	    }
   187	    println!("{sep}");
   188	    for row in rows {
   189	        println!("{}", fmt_row(row));
   190	    }
   191	}
   192	
   193	/// Entry point: banner, run the matrix, emit the table.
   194	fn main() {
   195	    let cli = Cli::parse();
   196	    println!("{TOP_ABOUT}");
   197	    let cfg: Cfg = cli.common.to_cfg(None);
   198	    let placements = discover_placements();
   199	    println!(
   200	        "{} cells, {:.1}s each; ns/msg = elapsed over messages moved; fills/msg = cross-core \
   201	         cache-line fills per message",
   202	        placements.len() * FLAVORS.len() * cfg.depths.len(),
   203	        cfg.duration.as_secs_f64(),
   204	    );
   205	    println!();
   206	
   207	    let mut cells: Vec<(&Placement, Flavor, u32, StreamResult)> = Vec::new();
   208	    for placement in &placements {
   209	        for flavor in FLAVORS {
   210	            for &depth in &cfg.depths {
   211	                if depth < flavor.min_depth() {
   212	                    eprintln!(
   213	                        "skipping {} {} depth {depth}: below the flavor's floor",
   214	                        placement.label,
   215	                        flavor.as_str()
   216	                    );
   217	                    continue;
   218	                }
   219	                eprintln!(
   220	                    "streaming {} {} depth {depth} ...",
   221	                    placement.label,
   222	                    flavor.as_str()
   223	                );
   224	                let res = run_stream(flavor, cfg.duration, placement.pin, depth);
   225	                cells.push((placement, flavor, depth, res));
   226	            }
   227	        }
   228	    }
   229	
   230	    let rows: Vec<Vec<String>> = cells
   231	        .iter()
   232	        .map(|(p, f, d, r)| {
   233	            vec![
   234	                p.label.clone(),
   235	                f.as_str().to_string(),
   236	                d.to_string(),
   237	                format!("{:.1}", r.secs * 1e9 / r.msgs.max(1) as f64),
   238	                format!("{:.1}M", r.msgs as f64 / 1e6),
   239	                fills_cell(r),
   240	            ]
   241	        })
   242	        .collect();
   243	    println!("Streaming costs (producer streams for the duration, consumer drains):");
   244	    println!();
   245	    print_table(
   246	        &[
   247	            "placement",
   248	            "flavor",
   249	            "depth",
   250	            "ns/msg",
   251	            "msgs",
   252	            "fills/msg",
   253	        ],
   254	        &rows,
   255	    );
   256	}

