    30	struct Cli {
    31	    #[command(flatten)]
    32	    common: CommonArgs,
    33	}
    34	
    35	/// Probe indices in [`CellResult::probes`] trip order.
    36	const M_SEND: usize = 0;
    37	const W_RECV: usize = 1;
    38	const W_SPIN: usize = 2;
    39	const W_ATT: usize = 3;
    40	const W_SEND: usize = 4;
    41	const M_RECV: usize = 5;
    42	const M_SPIN: usize = 6;
    43	const M_ATT: usize = 7;
