    74	    }
    75	}
    76	
    77	/// Round trips as a compact millions figure, e.g. `52.6M`.
    78	fn rts_cell(res: &CellResult) -> String {
    79	    format!("{:.1}M", res.rts as f64 / 1e6)
    80	}
    81	
    82	/// Print `rows` as an aligned markdown table under `headers`.
    83	/// The first two columns left-aligned, the rest right-aligned.
    84	/// The depth column is numeric, so it takes the right side.
    85	fn print_table(headers: &[&str], rows: &[Vec<String>]) {
    86	    let mut w: Vec<usize> = headers.iter().map(|h| h.len()).collect();
    87	    for row in rows {
    88	        for (i, cell) in row.iter().enumerate() {
    89	            w[i] = w[i].max(cell.len());
    90	        }
    91	    }
    92	    let fmt_row = |cells: &[String]| {
    93	        let mut line = String::from("|");
    94	        for (i, cell) in cells.iter().enumerate() {
    95	            if i < 2 {
    96	                line.push_str(&format!(" {:<w$} |", cell, w = w[i]));
    97	            } else {
    98	                line.push_str(&format!(" {:>w$} |", cell, w = w[i]));
    99	            }
   100	        }
   101	        line
   102	    };
   103	    let headers: Vec<String> = headers.iter().map(|h| h.to_string()).collect();
   104	    println!("{}", fmt_row(&headers));
   105	    let mut sep = String::from("|");
   106	    for (i, width) in w.iter().enumerate() {
   107	        if i < 2 {
   108	            sep.push_str(&format!("{}|", "-".repeat(width + 2)));
   109	        } else {
