   135	    let mut cells: Vec<(&Placement, Flavor, u32, CellResult)> = Vec::new();
   136	    for placement in &placements {
   137	        for flavor in FLAVORS {
   138	            for &depth in &cfg.depths {
   139	                if depth < flavor.min_depth() {
   140	                    eprintln!(
   141	                        "skipping {} {} depth {depth}: below the flavor's floor",
   142	                        placement.label,
   143	                        flavor.as_str()
   144	                    );
   145	                    continue;
   146	                }
   147	                eprintln!(
   148	                    "running {} {} depth {depth} ...",
   149	                    placement.label,
   150	                    flavor.as_str()
   151	                );
   152	                let res = run_cell(flavor, cfg.duration, placement.pin, depth);
   153	                cells.push((placement, flavor, depth, res));
   154	            }
