   168	                stat_cell(&r.probes[M_RECV], &cfg),
   169	                rts_cell(r),
   170	                fills_cell(r),
   171	            ]
   172	        })
   173	        .collect();
   174	    println!("Phase costs (send = reserve+fill+commit; recv = spin wait+read+release):");
   175	    println!();
   176	    print_table(
   177	        &[
   178	            "placement",
   179	            "flavor",
   180	            "depth",
   181	            "m.send",
   182	            "w.recv",
   183	            "w.send",
   184	            "m.recv",
   185	            "RTs",
   186	            "fills/RT",
   187	        ],
   188	        &phase_rows,
   189	    );
   190	    println!();
   191	
   192	    let spin_rows: Vec<Vec<String>> = cells
   193	        .iter()
   194	        .map(|(p, f, d, r)| {
   195	            vec![
   196	                p.label.clone(),
   197	                f.as_str().to_string(),
