     1	//! tp-matrix: run every flavor × placement round-trip cell and
     2	//! emit the two markdown tables (phase costs, spin
     3	//! decomposition) ready to paste, the one-command replacement
     4	//! for the perf(1)-and-scrape recipe.
     5	//!
     6	//! Placements are discovered from the CPU topology
     7	//! ([`tp_runner::topo`]): same cache domain, cross cache
     8	//! domain, SMT siblings, unpinned, whichever the machine has.
     9	//! Cells run sequentially in this process. Each cell re-pins
    10	//! (or unpins) the threads and collects its own fill counters.
    11	
    12	use clap::Parser;
    13	
    14	use tp_matrix::{CellResult, FLAVORS, Flavor, run_cell};
    15	use tp_runner::topo::{Placement, discover_placements};
    16	use tp_runner::{Cfg, CommonArgs};
    17	use tprobe::{TProbe, ticks};
    18	
    19	/// Banner: name, version, and tagline on one line, the first
    20	/// line of every run and of `-h`/`--help`.
    21	const TOP_ABOUT: &str = concat!(
    22	    "tp-matrix ",
    23	    env!("CARGO_PKG_VERSION"),
    24	    " - run the full measurement matrix, markdown tables out"
    25	);
    26	
    27	/// The tp-matrix CLI.
    28	#[derive(Parser, Debug)]
    29	#[command(name = "tp-matrix", version, about = TOP_ABOUT, max_term_width = 80)]
    30	struct Cli {
    31	    #[command(flatten)]
    32	    common: CommonArgs,
    33	}
    34	
    35	/// Probe indices in [`CellResult::probes`] trip order.
    36	const M_SEND: usize = 0;
    37	const W_RECV: usize = 1;
    38	const W_SPIN: usize = 2;
    39	const W_ATT: usize = 3;
    40	const W_SEND: usize = 4;
    41	const M_RECV: usize = 5;
    42	const M_SPIN: usize = 6;
    43	const M_ATT: usize = 7;
    44	
    45	/// One table cell: `mean/stdev` of the probe's trimmed min-p99
    46	/// band, ns by default, raw ticks under `-t`, raw counts for
    47	/// an attempts probe.
    48	fn stat_cell(p: &TProbe, cfg: &Cfg) -> String {
    49	    let Some((mean, stdev)) = p.trimmed_stats() else {
    50	        return "-".to_string();
    51	    };
    52	    let conv = if p.is_counts() || cfg.ticks {
    53	        1.0
    54	    } else {
    55	        ticks::ticks_per_ns()
    56	    };
    57	    let d = cfg.decimals;
    58	    format!("{:.d$}/{:.d$}", mean / conv, stdev / conv)
    59	}
    60	
    61	/// `fills/RT` cell: 3 decimals, or 4 when the value is tiny
    62	/// (the SMT cells), `-` when counters were unavailable.
    63	fn fills_cell(res: &CellResult) -> String {
    64	    match &res.fills {
    65	        Some(f) => {
    66	            let v = f.lcl_cache as f64 / res.rts.max(1) as f64;
    67	            if v < 0.01 {
    68	                format!("{v:.4}")
    69	            } else {
    70	                format!("{v:.3}")
    71	            }
    72	        }
    73	        None => "-".to_string(),
    74	    }
    75	}
    76	
    77	/// Round trips as a compact millions figure, e.g. `52.6M`.
    78	fn rts_cell(res: &CellResult) -> String {
    79	    format!("{:.1}M", res.rts as f64 / 1e6)
    80	}
    81	
    82	/// Print `rows` as an aligned markdown table under `headers`.
    83	/// The first two columns left-aligned, the rest right-aligned.
    84	/// The depth column is numeric, so it takes the right side.
    85	fn print_table(headers: &[&str], rows: &[Vec<String>]) {
    86	    let mut w: Vec<usize> = headers.iter().map(|h| h.len()).collect();
    87	    for row in rows {
    88	        for (i, cell) in row.iter().enumerate() {
    89	            w[i] = w[i].max(cell.len());
    90	        }
    91	    }
    92	    let fmt_row = |cells: &[String]| {
    93	        let mut line = String::from("|");
    94	        for (i, cell) in cells.iter().enumerate() {
    95	            if i < 2 {
    96	                line.push_str(&format!(" {:<w$} |", cell, w = w[i]));
    97	            } else {
    98	                line.push_str(&format!(" {:>w$} |", cell, w = w[i]));
    99	            }
   100	        }
   101	        line
   102	    };
   103	    let headers: Vec<String> = headers.iter().map(|h| h.to_string()).collect();
   104	    println!("{}", fmt_row(&headers));
   105	    let mut sep = String::from("|");
   106	    for (i, width) in w.iter().enumerate() {
   107	        if i < 2 {
   108	            sep.push_str(&format!("{}|", "-".repeat(width + 2)));
   109	        } else {
   110	            sep.push_str(&format!("{}:|", "-".repeat(width + 1)));
   111	        }
   112	    }
   113	    println!("{sep}");
   114	    for row in rows {
   115	        println!("{}", fmt_row(row));
   116	    }
   117	}
   118	
   119	/// Entry point: banner, run the matrix, emit the two tables.
   120	fn main() {
   121	    let cli = Cli::parse();
   122	    println!("{TOP_ABOUT}");
   123	    let cfg: Cfg = cli.common.to_cfg(None);
   124	    let placements = discover_placements();
   125	    let unit = if cfg.ticks { "tk" } else { "ns" };
   126	    println!(
   127	        "{} cells, {:.1}s each; phase cells are mean/stdev of the trimmed \
   128	         min-p99 band in {unit}; att in polls/waiting reserve; fills/RT = cross-core \
   129	         cache-line fills per round trip",
   130	        placements.len() * FLAVORS.len() * cfg.depths.len(),
   131	        cfg.duration.as_secs_f64(),
   132	    );
   133	    println!();
   134	
   135	    let mut cells: Vec<(&Placement, Flavor, u32, CellResult)> = Vec::new();
   136	    for placement in &placements {
   137	        for flavor in FLAVORS {
   138	            for &depth in &cfg.depths {
   139	                if depth < flavor.min_depth() {
   140	                    eprintln!(
   141	                        "skipping {} {} depth {depth}: below the flavor's floor",
   142	                        placement.label,
   143	                        flavor.as_str()
   144	                    );
   145	                    continue;
   146	                }
   147	                eprintln!(
   148	                    "running {} {} depth {depth} ...",
   149	                    placement.label,
   150	                    flavor.as_str()
   151	                );
   152	                let res = run_cell(flavor, cfg.duration, placement.pin, depth);
   153	                cells.push((placement, flavor, depth, res));
   154	            }
   155	        }
   156	    }
   157	
   158	    let phase_rows: Vec<Vec<String>> = cells
   159	        .iter()
   160	        .map(|(p, f, d, r)| {
   161	            vec![
   162	                p.label.clone(),
   163	                f.as_str().to_string(),
   164	                d.to_string(),
   165	                stat_cell(&r.probes[M_SEND], &cfg),
   166	                stat_cell(&r.probes[W_RECV], &cfg),
   167	                stat_cell(&r.probes[W_SEND], &cfg),
   168	                stat_cell(&r.probes[M_RECV], &cfg),
   169	                rts_cell(r),
   170	                fills_cell(r),
   171	            ]
   172	        })
   173	        .collect();
   174	    println!("Phase costs (send = reserve+fill+commit; recv = spin wait+read+release):");
   175	    println!();
   176	    print_table(
   177	        &[
   178	            "placement",
   179	            "flavor",
   180	            "depth",
   181	            "m.send",
   182	            "w.recv",
   183	            "w.send",
   184	            "m.recv",
   185	            "RTs",
   186	            "fills/RT",
   187	        ],
   188	        &phase_rows,
   189	    );
   190	    println!();
   191	
   192	    let spin_rows: Vec<Vec<String>> = cells
   193	        .iter()
   194	        .map(|(p, f, d, r)| {
   195	            vec![
   196	                p.label.clone(),
   197	                f.as_str().to_string(),
   198	                d.to_string(),
   199	                stat_cell(&r.probes[W_SPIN], &cfg),
   200	                stat_cell(&r.probes[W_ATT], &cfg),
   201	                stat_cell(&r.probes[M_SPIN], &cfg),
   202	                stat_cell(&r.probes[M_ATT], &cfg),
   203	                fills_cell(r),
   204	            ]
   205	        })
   206	        .collect();
   207	    println!("Spin decomposition (spin = first failed attempt -> reserve success):");
   208	    println!();
   209	    print_table(
   210	        &[
   211	            "placement",
   212	            "flavor",
   213	            "depth",
   214	            "w.spin",
   215	            "w.att",
   216	            "m.spin",
   217	            "m.att",
   218	            "fills/RT",
   219	        ],
   220	        &spin_rows,
   221	    );
   222	}
=== RUNNER ===
     1	//! Generic runner for phase-probed measurement examples: CLI
     2	//! config, thread pinning, and a fixed-duration round-trip
     3	//! drive loop over injected send/recv closures.
     4	//!
     5	//! - [`Cfg`] / [`CommonArgs`]: the runtime configuration and
     6	//!   the shared clap flags (`-d`/`--duration`, `-t`/`--ticks`,
     7	//!   `--decimals <n>`, `--depth <list>`) the binaries flatten
     8	//!   into their own `Parser` structs. [`parse_pin`] parses a
     9	//!   `--pin MAIN,WORKER` value.
    10	//! - [`LineBuf`]: a cache-line-aligned heap region sized at
    11	//!   runtime, so a cell's ring depth is a parameter rather
    12	//!   than a const.
    13	//! - [`pin_to_cpu`]: sched_setaffinity pinning (Linux, no-op
    14	//!   stub elsewhere).
    15	//! - [`drive`]: the round-trip loop: send a counter, receive
    16	//!   the echo. Probing lives in the caller's closures.
    17	//! - [`report`]: flavor header + the phase reports in trip
    18	//!   order.
    19	//! - [`perf`] (Linux): per-process hardware event counters
    20	//!   via `perf_event_open`, for cache-fill counting inside
    21	//!   measurement cells.
    22	//!
    23	//! Deliberately not a benchmark harness: no adaptive loop
    24	//! sizing, overhead calibration, or bench registry. For that
    25	//! scale of machinery, use iiac-perf.
    26	
    27	#[cfg(target_os = "linux")]
    28	pub mod perf;
    29	pub mod topo;
    30	
    31	use std::time::{Duration, Instant};
    32	
    33	use tprobe::TProbe;
    34	
    35	/// Sentinel available to callers as a shutdown message.
    36	/// [`drive`]'s counter skips it so payload values never
    37	/// collide with it.
    38	pub const STOP: u64 = u64::MAX;
    39	
    40	/// Iterations between wall-clock checks in [`drive`], keeping
    41	/// the per-iteration cost of `Instant::now` off the common
    42	/// path.
    43	const CLOCK_CHECK_EVERY: u64 = 4096;
    44	
    45	/// Bytes per cache line, the alignment [`LineBuf`] gives a
    46	/// region. The ring crate's `CACHE_LINE_SIZE` is the same
    47	/// number, and the cells assert the two agree.
    48	pub const LINE_BYTES: usize = 64;
    49	
    50	/// One cache line of backing store, so a run of them is a
    51	/// line-aligned region.
    52	#[derive(Clone, Copy)]
    53	#[repr(C, align(64))]
    54	struct CacheLine([u8; LINE_BYTES]);
    55	
    56	/// A cache-line-aligned heap region of at least the bytes asked
    57	/// for, zeroed, sized at runtime.
    58	///
    59	/// - The ring `init` functions take `&mut [u8]` and want it
    60	///   line-aligned. A const stack array fixes the depth per
    61	///   build, and this does not.
    62	/// - Heap against stack changes nothing a cell measures: the
    63	///   region is touched once at init and lives in cache after.
    64	pub struct LineBuf(Vec<CacheLine>);
    65	
    66	impl LineBuf {
    67	    /// A zeroed region of at least `bytes` bytes, rounded up to
    68	    /// whole lines.
    69	    pub fn new(bytes: u64) -> Self {
    70	        let lines = bytes.div_ceil(LINE_BYTES as u64) as usize;
    71	        LineBuf(vec![CacheLine([0; LINE_BYTES]); lines])
    72	    }
    73	
    74	    /// The region as bytes, for a ring's `init`.
    75	    pub fn as_mut_bytes(&mut self) -> &mut [u8] {
    76	        // SAFETY: the Vec is a contiguous run of `len` lines of
    77	        // initialised bytes, a `u8` view has no alignment
    78	        // requirement, and the borrow of `self` keeps the Vec
    79	        // alive and unaliased for the slice's lifetime.
    80	        unsafe {
    81	            core::slice::from_raw_parts_mut(
    82	                self.0.as_mut_ptr() as *mut u8,
    83	                self.0.len() * LINE_BYTES,
    84	            )
    85	        }
    86	    }
    87	}
    88	
    89	/// Runtime configuration for a probed measurement run, built
    90	/// from the parsed CLI args.
    91	pub struct Cfg {
    92	    /// Wall-clock budget per flavor.
    93	    pub duration: Duration,
    94	    /// Ring depths to run, each a power of two, every cell
    95	    /// repeated per depth.
    96	    pub depths: Vec<u32>,
    97	    /// `Some((main_cpu, worker_cpu))` pins both threads.
    98	    pub pin: Option<(usize, usize)>,
    99	    /// Report raw ticks instead of nanoseconds.
   100	    pub ticks: bool,
   101	    /// Fractional digits on report value columns.
   102	    pub decimals: usize,
   103	}
   104	
   105	/// The CLI flags shared by the probed measurement binaries,
   106	/// flattened via `#[command(flatten)]` into each binary's
   107	/// `Parser` struct.
   108	#[derive(clap::Args, Debug)]
   109	pub struct CommonArgs {
   110	    /// Wall-clock seconds per cell (each flavor × placement
   111	    /// combination runs this long)
   112	    #[arg(
   113	        short = 'd',
   114	        long = "duration",
   115	        value_name = "SECS",
   116	        default_value_t = 5.0
   117	    )]
   118	    pub duration: f64,
   119	
   120	    /// Report raw TSC ticks instead of nanoseconds
   121	    ///
   122	    /// Probes store hardware tick deltas. By default, reports
   123	    /// convert them to ns via the calibrated ticks-per-ns
   124	    /// ratio. This flag shows the stored ticks unconverted.
   125	    #[arg(short = 't', long)]
   126	    pub ticks: bool,
   127	
   128	    /// Fractional digits on report value columns
   129	    #[arg(long, value_name = "N", default_value_t = 1)]
   130	    pub decimals: usize,
   131	
   132	    /// Ring depths (slots per ring) to run, comma-separated
   133	    /// powers of two. Every cell repeats per depth
   134	    ///
   135	    /// One message is ever in flight in a round-trip cell, so
   136	    /// the depth changes how many seq words share a line and,
   137	    /// at 1, whether the ring has any slack at all.
   138	    #[arg(
   139	        long,
   140	        value_name = "LIST",
   141	        value_delimiter = ',',
   142	        default_value = "8",
   143	        value_parser = parse_depth
   144	    )]
   145	    pub depth: Vec<u32>,
   146	}
   147	
   148	impl CommonArgs {
   149	    /// Build the runtime [`Cfg`], attaching the binary-specific
   150	    /// `pin` (only `tp-cell` exposes one).
   151	    pub fn to_cfg(&self, pin: Option<(usize, usize)>) -> Cfg {
   152	        Cfg {
   153	            duration: Duration::from_secs_f64(self.duration),
   154	            depths: self.depth.clone(),
   155	            pin,
   156	            ticks: self.ticks,
   157	            decimals: self.decimals,
   158	        }
   159	    }
   160	}
   161	
   162	/// clap value parser for one `--depth` element: a power of two
   163	/// from 1 up, the ring geometry every flavor accepts.
   164	pub fn parse_depth(s: &str) -> Result<u32, String> {
   165	    let d: u32 = s
   166	        .trim()
   167	        .parse()
   168	        .map_err(|_| format!("depth is not a number: `{s}`"))?;
   169	    if d == 0 || !d.is_power_of_two() {
   170	        return Err(format!("depth must be a power of two from 1 up, got {d}"));
   171	    }
   172	    Ok(d)
   173	}
   174	
   175	/// clap value parser for `--pin MAIN,WORKER`: two
   176	/// comma-separated logical CPU numbers.
   177	pub fn parse_pin(s: &str) -> Result<(usize, usize), String> {
   178	    let (m, w) = s
   179	        .split_once(',')
   180	        .ok_or_else(|| format!("expected MAIN,WORKER (e.g. 0,1), got `{s}`"))?;
   181	    let m = m
   182	        .trim()
   183	        .parse()
   184	        .map_err(|_| format!("MAIN is not a CPU number: `{m}`"))?;
   185	    let w = w
   186	        .trim()
   187	        .parse()
   188	        .map_err(|_| format!("WORKER is not a CPU number: `{w}`"))?;
   189	    Ok((m, w))
   190	}
   191	
   192	/// Pin the calling thread to `cpu` via sched_setaffinity.
   193	/// Panics on failure (a run with a silently ignored pin would
   194	/// report a mislabeled number).
   195	#[cfg(target_os = "linux")]
   196	pub fn pin_to_cpu(cpu: usize) {
   197	    // SAFETY: cpu_set_t is a plain bitmask. CPU_ZERO/CPU_SET
   198	    // initialize it fully before sched_setaffinity reads it.
   199	    unsafe {
   200	        let mut set: libc::cpu_set_t = std::mem::zeroed();
   201	        libc::CPU_ZERO(&mut set);
   202	        libc::CPU_SET(cpu, &mut set);
   203	        let rc = libc::sched_setaffinity(0, size_of::<libc::cpu_set_t>(), &set);
   204	        assert_eq!(rc, 0, "sched_setaffinity({cpu}) failed");
   205	    }
   206	}
   207	
   208	/// Non-Linux stub: `--pin` becomes a no-op.
   209	#[cfg(not(target_os = "linux"))]
   210	pub fn pin_to_cpu(_cpu: usize) {}
   211	
   212	/// Reset the calling thread's affinity to every online CPU:
   213	/// the undo for [`pin_to_cpu`], needed when one process runs
   214	/// pinned and unpinned cells in sequence.
   215	#[cfg(target_os = "linux")]
   216	pub fn unpin_current() {
   217	    // SAFETY: cpu_set_t is a plain bitmask. CPU_ZERO/CPU_SET
   218	    // initialize it fully before sched_setaffinity reads it.
   219	    unsafe {
   220	        let mut set: libc::cpu_set_t = std::mem::zeroed();
   221	        libc::CPU_ZERO(&mut set);
   222	        let n = libc::sysconf(libc::_SC_NPROCESSORS_ONLN).max(1) as usize;
   223	        for cpu in 0..n {
   224	            libc::CPU_SET(cpu, &mut set);
   225	        }
   226	        let rc = libc::sched_setaffinity(0, size_of::<libc::cpu_set_t>(), &set);
   227	        assert_eq!(rc, 0, "sched_setaffinity(all) failed");
   228	    }
   229	}
   230	
   231	/// Non-Linux stub: affinity is untouched, so nothing to undo.
   232	#[cfg(not(target_os = "linux"))]
   233	pub fn unpin_current() {}
   234	
   235	/// A spin wait policy: hint and keep trying. Matches the
   236	/// `on_full`/`on_empty` closure shape of the ring endpoints.
   237	pub fn spin(_attempt: u32) -> bool {
   238	    core::hint::spin_loop();
   239	    true
   240	}
   241	
   242	/// Drive `dur` worth of round trips: send the counter via
   243	/// `send`, receive the echo via `recv`. Returns when the
   244	/// budget is spent (checked every [`CLOCK_CHECK_EVERY`]
   245	/// iterations). The counter skips [`STOP`] so callers can use
   246	/// it as a shutdown sentinel afterwards.
   247	///
   248	/// All probing lives in the closures. The loop itself
   249	/// measures nothing, so callers control exactly what each
   250	/// probe brackets (and record into their histograms *after*
   251	/// their phase-end tick reads, off the measured path).
   252	pub fn drive(dur: Duration, mut send: impl FnMut(u64), mut recv: impl FnMut() -> u64) {
   253	    let start = Instant::now();
   254	    let mut counter: u64 = 0;
   255	    loop {
   256	        for _ in 0..CLOCK_CHECK_EVERY {
   257	            counter = counter.wrapping_add(1);
   258	            if counter == STOP {
   259	                counter = 1;
   260	            }
   261	            send(counter);
   262	            let v = recv();
   263	            assert_eq!(v, counter, "echo mismatch");
   264	        }
   265	        if start.elapsed() >= dur {
   266	            return;
   267	        }
   268	    }
   269	}
   270	
   271	/// Print one flavor's header, then its phase reports in the
   272	/// order given (conventionally trip order: main send -> worker
   273	/// recv -> worker send -> main recv).
   274	pub fn report(flavor: &str, cfg: &Cfg, depth: u32, probes: impl IntoIterator<Item = TProbe>) {
   275	    let pin = match cfg.pin {
   276	        Some((m, w)) => format!("main={m},worker={w}"),
   277	        None => "none".to_string(),
   278	    };
   279	    println!(
   280	        "{flavor} round trip [duration={:.1}s pin={pin} depth={depth}]:",
   281	        cfg.duration.as_secs_f64(),
   282	    );
   283	    for p in probes {
   284	        p.report(cfg.ticks, cfg.decimals);
   285	    }
   286	}

