     1	//! CPU topology discovery for measurement placements: derive
     2	//! the interesting 2-thread pin pairs from /sys, anchored on
     3	//! cpu 0.
     4	//!
     5	//! - same cache domain (another core sharing cpu 0's L3);
     6	//! - cross cache domain (a core outside cpu 0's L3);
     7	//! - SMT siblings (cpu 0's hyper-thread, shared L1/L2);
     8	//! - unpinned (scheduler's choice).
     9	//!
    10	//! Pairs the machine doesn't have (no SMT, single L3 domain)
    11	//! are simply absent; non-Linux gets only the unpinned entry.
    12	
    13	/// One placement cell: a display label and the `(main, worker)`
    14	/// pin pair (`None` = unpinned).
    15	pub struct Placement {
    16	    /// Table label, e.g. `"0,1 CCX"`, `"0,12 SMT"`,
    17	    /// `"unpinned"`.
    18	    pub label: String,
    19	    /// `(main_cpu, worker_cpu)`, or `None` for unpinned.
    20	    pub pin: Option<(usize, usize)>,
    21	}
    22	
    23	/// Parse a /sys cpu-list string ("0,12" or "0-2,6") into cpu
    24	/// numbers; malformed pieces are skipped.
    25	#[cfg(target_os = "linux")]
    26	fn parse_cpu_list(s: &str) -> Vec<usize> {
    27	    let mut out = Vec::new();
    28	    for part in s.trim().split(',') {
    29	        match part.split_once('-') {
    30	            Some((lo, hi)) => {
    31	                if let (Ok(lo), Ok(hi)) = (lo.parse::<usize>(), hi.parse::<usize>()) {
    32	                    out.extend(lo..=hi);
    33	                }
    34	            }
    35	            None => {
    36	                if let Ok(n) = part.parse() {
    37	                    out.push(n);
    38	                }
    39	            }
    40	        }
    41	    }
    42	    out
    43	}
    44	
    45	/// Discover the placement cells for this machine, in
    46	/// same-domain → cross-domain → SMT → unpinned order.
    47	#[cfg(target_os = "linux")]
    48	pub fn discover_placements() -> Vec<Placement> {
    49	    let read = |path: &str| std::fs::read_to_string(path).ok();
    50	    let siblings = read("/sys/devices/system/cpu/cpu0/topology/thread_siblings_list")
    51	        .map(|s| parse_cpu_list(&s))
    52	        .unwrap_or_default();
    53	    let online = read("/sys/devices/system/cpu/online")
    54	        .map(|s| parse_cpu_list(&s))
    55	        .unwrap_or_default();
    56	    let l3 = read("/sys/devices/system/cpu/cpu0/cache/index3/shared_cpu_list")
    57	        .map(|s| parse_cpu_list(&s))
    58	        .unwrap_or_else(|| siblings.clone());
    59	
    60	    let mut v = Vec::new();
    61	    if let Some(c) = l3
    62	        .iter()
    63	        .copied()
    64	        .find(|&c| c != 0 && !siblings.contains(&c))
    65	    {
    66	        v.push(Placement {
    67	            label: format!("0,{c} CCX"),
    68	            pin: Some((0, c)),
    69	        });
    70	    }
    71	    if let Some(c) = online.iter().copied().find(|c| !l3.contains(c)) {
    72	        v.push(Placement {
    73	            label: format!("0,{c} x-CCX"),
    74	            pin: Some((0, c)),
    75	        });
    76	    }
    77	    if siblings.len() >= 2 && siblings[0] == 0 {
    78	        let sib = siblings[1];
    79	        v.push(Placement {
    80	            label: format!("0,{sib} SMT"),
    81	            pin: Some((0, sib)),
    82	        });
    83	    }
    84	    v.push(Placement {
    85	        label: "unpinned".to_string(),
    86	        pin: None,
    87	    });
    88	    v
    89	}
    90	
    91	/// Non-Linux stub: no /sys topology — unpinned only.
    92	#[cfg(not(target_os = "linux"))]
    93	pub fn discover_placements() -> Vec<Placement> {
    94	    vec![Placement {
    95	        label: "unpinned".to_string(),
    96	        pin: None,
    97	    }]
    98	}
